const items=$input.all();
const CUT='2022-01-01';
const FRESH=Date.now()-400*86400000;
function unitArr(j,ns,name,unit){try{const c=j.facts[ns][name].units[unit];return Array.isArray(c)?c:[];}catch(e){return [];}}
function annualNewest(j,ns,names,unit){var best=null;for(var n=0;n<names.length;n++){var a=unitArr(j,ns,names[n],unit);for(var i=0;i<a.length;i++){var e=a[i];if(!e.start||!e.end)continue;var days=(new Date(e.end)-new Date(e.start))/86400000;if(days>=340&&days<=380){if(!best||new Date(e.end)>new Date(best.end))best=e;}}}return best;}
function latestInstant(entries){var best=null;for(var i=0;i<entries.length;i++){var e=entries[i];var end=e.end||e.instant;if(!end)continue;if(!best||new Date(end)>new Date(best.end||best.instant))best=e;}return best;}
var REV=['Revenues','RevenueFromContractWithCustomerIncludingAssessedTax','RevenueFromContractWithCustomerExcludingAssessedTax','SalesRevenueNet','RevenuesNetOfInterestExpense'];
var rawDefs=[['us-gaap','RevenueFromContractWithCustomerExcludingAssessedTax','USD'],['us-gaap','Revenues','USD'],['us-gaap','SalesRevenueNet','USD'],['us-gaap','RevenuesNetOfInterestExpense','USD'],['us-gaap','NetIncomeLoss','USD'],['us-gaap','StockholdersEquity','USD'],['us-gaap','Assets','USD'],['us-gaap','Liabilities','USD'],['us-gaap','CashAndCashEquivalentsAtCarryingValue','USD'],['us-gaap','LongTermDebtNoncurrent','USD'],['dei','EntityCommonStockSharesOutstanding','shares']];
var out=[];
for(var k=0;k<items.length;k++){
  var it=items[k];var j=(it.json&&it.json.facts)?it.json:((it.json&&it.json.body&&it.json.body.facts)?it.json.body:null);
  if(!j||!j.facts)continue;
  var cik=Number(j.cik);if(!cik)continue;
  var facts=[];
  for(var d=0;d<rawDefs.length;d++){var a=unitArr(j,rawDefs[d][0],rawDefs[d][1],rawDefs[d][2]);for(var m=0;m<a.length;m++){var e=a[m];var end=e.end||e.instant||null;var start=e.start||end;if(e.filed&&e.filed<CUT)continue;if(end==null||start==null||e.val==null)continue;facts.push({concept:rawDefs[d][1],unit:rawDefs[d][2],start:start,end:end,val:e.val,form:e.form||null,filed:e.filed||null,accn:e.accn||null});}}
  var rev=annualNewest(j,'us-gaap',REV,'USD');
  var ni=annualNewest(j,'us-gaap',['NetIncomeLoss','ProfitLoss'],'USD');
  var eq=latestInstant(unitArr(j,'us-gaap','StockholdersEquity','USD'));
  var as=latestInstant(unitArr(j,'us-gaap','Assets','USD'));
  var li=latestInstant(unitArr(j,'us-gaap','Liabilities','USD'));
  var ca=latestInstant(unitArr(j,'us-gaap','CashAndCashEquivalentsAtCarryingValue','USD'));
  var de=latestInstant(unitArr(j,'us-gaap','LongTermDebtNoncurrent','USD'));
  var sh=latestInstant(unitArr(j,'dei','EntityCommonStockSharesOutstanding','shares'));
  if(!sh)sh=latestInstant(unitArr(j,'us-gaap','CommonStockSharesOutstanding','shares'));
  var freshRev=(rev&&(new Date(rev.end).getTime()>FRESH))?rev:null;
  var fund=freshRev?{cik:cik,revenue_ttm:freshRev.val,revenue_asof:freshRev.end,revenue_basis:'annual',net_income_ttm:(ni?ni.val:null),net_income_asof:(ni?ni.end:null),net_income_basis:'annual',equity:(eq?eq.val:null),equity_end:(eq?(eq.end||eq.instant):null),shares:(sh?sh.val:null),shares_asof:(sh?(sh.end||sh.instant):null),shares_src:(sh?'edgar':null),assets:(as?as.val:null),liabilities:(li?li.val:null),cash:(ca?ca.val:null),debt:(de?de.val:null),currency:'USD',note:'edgar-feed annual'}:null;
  out.push({json:{cik:cik,facts:facts,fund:fund,fact_n:facts.length,has_fund:!!fund}});
}
return out;
